<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {memberFeedbackApi} from '../api/memberFeedback';
import {latestReports,type GrowthReport} from '../lib/growthReport';
import {appealTypes,canRereview,charCount,channelState,appealDeadline,decodeAppeal,encodeAppeal,needsScope,scopeOptions,validAppealScope,statusInfo,type MemberAppeal} from '../lib/memberFeedback';
const reports=ref<GrowthReport[]>([]),records=ref<MemberAppeal[]>([]),cycleId=ref(''),type=ref(''),scope=ref(''),reason=ref('');
const loading=ref(true),listLoading=ref(true),reportError=ref(''),listError=ref(''),message=ref(''),error=ref(''),busy=ref(false),now=ref(Date.now());
const selected=ref<MemberAppeal|null>(null),dialog=ref<HTMLDialogElement|null>(null),rereviewReason=ref(''),detailError=ref('');let timer:ReturnType<typeof setInterval>|undefined,alive=true;
const report=computed(()=>reports.value.find(r=>r.cycleId===cycleId.value));
const channel=computed(()=>channelState(report.value?.publishedAt,now.value));
const channelLabel=computed(()=>({OPEN:'申诉通道开放中',CLOSED:'申诉通道已关闭',UNAVAILABLE:'申诉通道未开放'}[channel.value]));
const availableScopes=computed(()=>scopeOptions(type.value));
watch(type,()=>{scope.value='';error.value='';});
const existing=computed(()=>records.value.find(r=>r.cycleId===cycleId.value));
const count=computed(()=>charCount(reason.value));
function date(value?:string){if(!value)return '暂未提供';const d=new Date(value);return Number.isNaN(d.getTime())?'暂未提供':d.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function range(r:GrowthReport){return `${date(r.openAt).split(' ')[0]} — ${date(r.closeAt).split(' ')[0]}`;}
function period(id:string){return reports.value.find(r=>r.cycleId===id)?.month??'历史评价周期';}
function friendly(e:unknown){const code=e instanceof Error?e.message:String(e);return ({FEEDBACK_DUPLICATED:'本周期已有申请，请查看原记录；符合条件时可申请二次复核。',FEEDBACK_TYPE_INVALID:'请选择有效的申诉类型。',FEEDBACK_SCOPE_INVALID:'涉及评价范围与申诉类型不匹配，请重新选择。',FEEDBACK_REASON_INVALID:'请填写有效反馈理由，最多500字。',FEEDBACK_WINDOW_CLOSED:'当前申诉通道已关闭，无法提交首次申请。',PUBLICATION_NOT_FOUND:'未找到本人已发布结果，请重新加载。',NOT_OWN_RESULT:'无权访问这份申诉或评价结果。',REREVIEW_NOT_ALLOWED:'该记录当前不允许再次复核，请刷新状态。',REQUEST_TIMEOUT:'请求超时，请稍后重试。',HTTP_401:'登录已失效，请重新登录。',HTTP_403:'当前身份无权访问。'} as Record<string,string>)[code]??'请求未完成，请检查网络后重试。';}
async function loadReports(){loading.value=true;reportError.value='';try{const rows=await memberFeedbackApi.reports();if(!alive)return;reports.value=latestReports(rows);if(!reports.value.some(r=>r.cycleId===cycleId.value))cycleId.value=reports.value[0]?.cycleId??'';}catch(e){if(alive)reportError.value=friendly(e);}finally{if(alive)loading.value=false;}}
async function loadRecords(){listLoading.value=true;listError.value='';try{const rows=await memberFeedbackApi.list();if(!alive)return;records.value=rows;if(selected.value)selected.value=rows.find(r=>r.id===selected.value?.id)??selected.value;}catch(e){if(alive)listError.value=friendly(e);}finally{if(alive)listLoading.value=false;}}
function cycleChanged(){scope.value='';error.value='';}
function validation(){if(!report.value)return '请选择本人已发布结果的周期。';if(channel.value!=='OPEN')return '当前周期不在首次申诉开放期内。';if(listLoading.value||listError.value)return '请先成功加载反馈记录，再提交申请。';if(existing.value)return '本周期已有申请，请查看原记录；符合条件时可申请二次复核。';if(!appealTypes.includes(type.value))return '请选择申诉类型。';if(!validAppealScope(type.value,scope.value))return '请选择与申诉类型对应的评价范围。';if(!count.value||count.value>500)return '请填写有效反馈理由，最多500字。';return '';}
async function submit(){if(busy.value)return;error.value=validation();message.value='';if(error.value)return;busy.value=true;try{await memberFeedbackApi.create(report.value!.id,encodeAppeal(type.value,scope.value?[scope.value]:[],reason.value));reason.value='';type.value='';scope.value='';message.value='反馈申请已提交。';await loadRecords();if(listError.value)message.value='申请已提交，记录刷新失败。请刷新列表，勿重复提交。';}catch(e){error.value=friendly(e);}finally{busy.value=false;}}
function showDetail(record:MemberAppeal){selected.value=record;rereviewReason.value='';detailError.value='';dialog.value?.showModal();}
async function rereview(){if(busy.value||!selected.value||!canRereview(selected.value.status))return;if(!charCount(rereviewReason.value)||charCount(rereviewReason.value)>500){detailError.value='请填写二次复核理由，最多500字。';return;}busy.value=true;detailError.value='';try{const result=await memberFeedbackApi.rereview(selected.value.id,rereviewReason.value.trim());rereviewReason.value='';await loadRecords();if(listError.value){detailError.value='复核已提交，刷新失败。请关闭详情并刷新列表。';selected.value={...selected.value,status:result.status};}else message.value='二次复核申请已提交。';}catch(e){detailError.value=friendly(e);}finally{busy.value=false;}}
onMounted(()=>{void loadReports();void loadRecords();timer=setInterval(()=>now.value=Date.now(),30000);});onUnmounted(()=>{alive=false;if(timer)clearInterval(timer);});
</script>
<template>
 <div class="personal-standard feedback-workspace member-feedback">
  <header class="page-head"><div><h1 class="page-title">反馈申诉</h1><p class="page-sub">对已发布的评价结果存在异议时，可在规定时间内提交反馈申请。</p></div><aside class="channel" :class="channel.toLowerCase()"><span aria-hidden="true">ⓘ</span><div><strong>{{loading?'正在读取通道状态':reportError?'申诉通道暂不可用':channelLabel}}</strong><small v-if="report">申诉截止：{{date(appealDeadline(report.publishedAt)?.toISOString())}}</small><small v-else>本人评价结果发布后可查看申请窗口</small></div></aside></header>
  <div v-if="message" class="notice success" role="status">{{message}}</div>
  <section class="card application"><h2>发起反馈申请</h2>
   <div v-if="reportError" class="notice failure" role="alert">{{reportError}} <button class="text-button" @click="loadReports">重新加载</button></div>
   <div v-else-if="!loading&&!reports.length" class="notice">当前尚无本人已发布的评价结果，申诉通道未开放。</div>
   <form @submit.prevent="submit" novalidate>
    <div class="form-grid">
     <div class="field"><label for="appeal-cycle">关联周期 <em>*</em></label><select id="appeal-cycle" :title="report?report.month+'（'+range(report)+'）':'暂无已发布周期'" v-model="cycleId" :disabled="loading||busy||!!reportError||!reports.length" @change="cycleChanged"><option v-if="!reports.length" value="">暂无已发布周期</option><option v-for="r in reports" :key="r.id" :value="r.cycleId">{{r.month}}（{{range(r)}}）</option></select></div>
     <div class="field"><label for="appeal-type">申诉类型 <em>*</em></label><select id="appeal-type" v-model="type" :disabled="busy" aria-required="true"><option value="">请选择申诉类型</option><option v-for="t in appealTypes" :key="t">{{t}}</option></select></div>
     <div class="field"><label for="appeal-scope">涉及评价范围 <em v-if="needsScope(type)">*</em></label><select id="appeal-scope" v-model="scope" :disabled="!type||type==='其他问题'||busy" :aria-required="needsScope(type)"><option value="">{{!type?'请先选择申诉类型':type==='其他问题'?'此类型无需选择范围':'请选择涉及评价范围'}}</option><option v-for="option in availableScopes" :key="option" :value="option">{{option}}</option></select></div>
    </div>
    <label class="reason-label" for="appeal-reason">反馈理由 <em>*</em></label><div class="reason-input"><textarea id="appeal-reason" v-model="reason" :disabled="busy" rows="4" aria-required="true" :aria-invalid="count>500" placeholder="请具体说明存在异议的内容、原因及相关事实依据，便于审核人员核实。"/><small :class="{invalid:count>500}">{{count}} / 500</small></div>
    <div class="form-footer"><p>请提供具体事实依据。首次申诉窗口按发布后3个工作日计算，仅跳过周末。</p><button class="btn btn-primary" :disabled="busy||loading||channel!=='OPEN'||listLoading||!!listError||!!existing||!!reportError" type="submit">{{busy?'正在提交…':'提交申请'}}</button></div>
    <p v-if="existing" class="form-hint">本周期已有申请，请查看下方记录；符合条件时可申请二次复核。</p><p v-else-if="report&&channel==='CLOSED'" class="form-hint">本周期申诉通道已关闭，仍可查看历史记录。</p><p v-if="error" class="failure" role="alert">{{error}}</p>
   </form>
  </section>
  <section class="card records"><div class="records-heading"><h2>我的反馈记录</h2><div><span>共 {{records.length}} 条记录</span><button class="text-button" :disabled="listLoading||busy" @click="loadRecords">刷新</button></div></div>
   <div v-if="listLoading" class="empty" role="status">正在读取反馈记录…</div><div v-else-if="listError" class="notice failure" role="alert">{{listError}} <button class="text-button" @click="loadRecords">重试</button></div><div v-else-if="!records.length" class="empty">暂无反馈记录，提交后的申请会显示在这里。</div>
   <article v-for="r in listError||listLoading?[]:records" :key="r.id" class="record"><div class="record-main"><div class="record-title"><h3>{{period(r.cycleId)}} · {{decodeAppeal(r.reason).type}}</h3><span class="state" :class="statusInfo(r.status).tone">{{statusInfo(r.status).label}}</span></div><small>提交时间：{{date(r.createdAt)}}</small><small>涉及范围：{{decodeAppeal(r.reason).scope}}</small><p class="excerpt">{{decodeAppeal(r.reason).reason}}</p></div><div class="record-progress"><strong>{{statusInfo(r.status).label}}</strong><small>最近已知时间：{{date(r.updatedAt||r.handledAt||r.rereviewOpenedAt||r.createdAt)}}</small><p>{{r.handlerNote||(['DONE','REJECTED','REREVIEW_DONE','REREVIEW_REJECTED'].includes(r.status)?'处理状态已更新，详细处理意见暂未提供。':'申请状态以处理人员的实际更新为准。')}}</p></div><button class="btn detail-button" @click="showDetail(r)">查看详情</button></article>
  </section>
  <dialog ref="dialog" class="appeal-detail" aria-labelledby="detail-title" @close="selected=null"><template v-if="selected"><header><h2 id="detail-title">申诉详情</h2><button class="close" aria-label="关闭申诉详情" @click="dialog?.close()">×</button></header><div class="detail-body"><dl><dt>评价周期</dt><dd>{{period(selected.cycleId)}}</dd><dt>申诉类型</dt><dd>{{decodeAppeal(selected.reason).type}}</dd><dt>涉及评价范围</dt><dd>{{decodeAppeal(selected.reason).scope}}</dd><dt>当前状态</dt><dd><span class="state" :class="statusInfo(selected.status).tone">{{statusInfo(selected.status).label}}</span></dd><dt>提交时间</dt><dd>{{date(selected.createdAt)}}</dd><dt>完整申诉理由</dt><dd class="full-text">{{decodeAppeal(selected.reason).reason}}</dd><dt>处理结论</dt><dd>{{['DONE','REJECTED','REREVIEW_DONE','REREVIEW_REJECTED'].includes(selected.status)?statusInfo(selected.status).label:'处理结果尚未公布'}}</dd><dt>管理员反馈意见</dt><dd class="full-text">{{selected.handlerNote||'接口暂未提供处理意见'}}</dd><dt>处理完成时间</dt><dd>{{date(selected.handledAt)}}</dd><template v-if="selected.rereviewOpenedAt"><dt>二次复核申请时间</dt><dd>{{date(selected.rereviewOpenedAt)}}</dd><dt>二次复核理由</dt><dd class="full-text">{{selected.rereviewReason||'暂未提供'}}</dd></template></dl><p class="detail-note">仅展示本人申诉及接口已提供的信息，不展示内部审核记录。</p><section v-if="canRereview(selected.status)" class="rereview"><h3>申请二次复核</h3><label for="rereview-reason">复核理由</label><textarea id="rereview-reason" v-model="rereviewReason" :disabled="busy" rows="3" placeholder="请说明申请二次复核的具体原因"/><small>{{charCount(rereviewReason)}} / 500</small><button class="btn btn-primary" :disabled="busy" @click="rereview">{{busy?'正在提交…':'申请二次复核'}}</button></section><p v-if="detailError" class="failure" role="alert">{{detailError}}</p></div></template></dialog>
 </div>
</template>
<style scoped>
.member-feedback{color:#172b4d}.page-head{margin-bottom:22px}.channel{display:flex;gap:12px;align-items:center;min-width:270px;max-width:100%;padding:14px 16px;border-radius:9px;background:#eef3fa;color:#667085}.channel.open{background:#eaf1ff;color:#246bfd}.channel>span{font-size:23px}.channel strong,.channel small{display:block}.channel strong{font-size:13px}.channel small{margin-top:4px;font-size:12px;line-height:20px}.card{padding:24px;border:1px solid #e5eaf2;box-shadow:0 3px 12px #172b4d04;margin-bottom:20px}h2{font-size:18px;line-height:26px;margin:0 0 20px}h3{font-size:15px;line-height:24px;margin:0}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-bottom:20px}.field{margin:0;min-width:0}label,legend{font-size:13px;color:#53637b}label{display:block;margin-bottom:7px}em{color:#d44848;font-style:normal}.field select,textarea{width:100%;min-width:0;border:1px solid #dce3ed;background:#fff;color:#172b4d;font:inherit;border-radius:7px;padding:10px 12px}.field select{height:40px}textarea{display:block;resize:vertical;line-height:22px;font-size:14px}.field select:focus,textarea:focus{outline:2px solid #c7d9ff;border-color:#246bfd}.reason-input{position:relative}.reason-input textarea{padding-bottom:28px;min-height:110px}.reason-input>small{position:absolute;bottom:8px;right:12px;color:#8492a8;font-size:12px}.reason-input>small.invalid{color:#b42318}.form-footer{display:flex;gap:20px;justify-content:space-between;align-items:center;margin-top:12px}.form-footer p,.form-hint{color:#8492a8;font-size:12px;line-height:20px;margin:0}.form-footer button{flex:none}.form-hint{margin-top:12px;color:#667085}.records-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.records-heading h2{margin:0}.records-heading>div{display:flex;gap:12px;align-items:center;font-size:12px;color:#8492a8}.record{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr) auto;gap:22px;align-items:center;padding:20px;border:1px solid #e5eaf2;border-radius:10px;margin-top:12px}.record-title{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:6px}.record small{display:block;color:#8492a8;font-size:12px;line-height:20px}.record p{font-size:13px;line-height:22px;color:#667085;margin:12px 0 0;overflow-wrap:anywhere}.excerpt{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;white-space:pre-wrap}.record-progress{padding-left:20px;border-left:1px solid #e5eaf2;min-width:0}.record-progress>strong{font-size:13px;font-weight:500}.record-progress p{background:#f7f9fc;padding:9px 12px;border-radius:6px}.state{display:inline-block;font-size:12px;padding:2px 7px;border-radius:4px;line-height:20px}.orange{background:#fff3e3;color:#bd791e}.blue{background:#edf3ff;color:#246bfd}.green{background:#eaf8f0;color:#258363}.gray{background:#f1f3f6;color:#667085}.text-button{border:0;background:none;padding:0;font:inherit;color:#246bfd;cursor:pointer}.text-button:disabled{color:#a4adba;cursor:not-allowed}.success{border-color:#d1e8da;background:#f0faf4;color:#258363;margin-bottom:16px}.failure{color:#b42318;font-size:13px;line-height:22px}.application>.notice{margin-bottom:18px}.empty{padding:38px 16px;text-align:center;color:#8492a8}.appeal-detail{position:fixed;inset:0 0 0 auto;margin:0;width:min(560px,100vw);max-width:100vw;height:100dvh;max-height:100dvh;padding:0;border:0;color:#172b4d;box-shadow:-12px 0 40px #172b4d22}.appeal-detail::backdrop{background:#172b4d55}.appeal-detail header{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;border-bottom:1px solid #e5eaf2}.appeal-detail h2{margin:0}.close{width:32px;height:32px;border:0;border-radius:6px;font-size:25px;background:#f4f7fc;color:#667085;cursor:pointer}.detail-body{padding:24px}dl{margin:0}dt{font-size:12px;color:#8492a8;margin-top:16px}dt:first-child{margin-top:0}dd{margin:5px 0 0;font-size:14px;line-height:24px;overflow-wrap:anywhere}.full-text{white-space:pre-wrap}.detail-note{padding:10px;background:#f4f7fc;border-radius:7px;font-size:12px;line-height:21px;color:#667085}.rereview{margin-top:20px;padding-top:20px;border-top:1px solid #e5eaf2}.rereview h3{margin-bottom:12px}.rereview small{display:block;text-align:right;color:#8492a8;margin:4px 0 12px}button:focus-visible{outline:3px solid #b3cdfd;outline-offset:2px}@media(max-width:1100px){.form-grid{gap:16px;grid-template-columns:repeat(2,minmax(0,1fr))}.record{grid-template-columns:minmax(0,1fr) auto}.record-progress{grid-column:1/-1;border-left:0;border-top:1px solid #e5eaf2;padding:14px 0 0;order:3}}@media(max-width:680px){.page-head{flex-direction:column;align-items:flex-start}.channel{width:100%}.card{padding:18px 16px}.form-grid{grid-template-columns:1fr}.form-footer{align-items:flex-start;flex-direction:column;gap:12px}.form-footer button{align-self:flex-end}.record{padding:16px;gap:12px}.record-title{align-items:flex-start;flex-direction:column}.detail-button{font-size:12px;padding:8px}.detail-body{padding:20px}}
</style>
